const inventoryRegionDetailResponse="③ 存货项目明细\n[[\"土耳其代表处\", \"土耳其\", \"运营商\", \"Turk Telekom 5G Wireless Project\", \"0.85\", \"低\", \"4-6月\", \"TT客户5G首发项目，以新建+GUL扩容为主，站点交付方案设计复杂，包括TK、RFI、多制式协同，分包资源需求大，导致站点在建超期0.78M，当前业务持续滚动交付中。\"], [\"土耳其代表处\", \"土耳其\", \"运营商\", \"Turkey Turksat Universal MS&Rollout 2022 Project\", \"0.82\", \"未提供\", \"4-12月\", \"U3项目超期较26Q1无明显变化，客户Turksat代政府主导执行的农村网络项目，以TK交付场景为主，超期主要集中在建存货0.68M，业务滚动交付和持续安装中，Q2评估结论：不计提专项。\"], [\"土耳其代表处\", \"土耳其\", \"运营商\", \"Turk Telekom Wireless Project\", \"0.67\", \"未提供\", \"4-10月\", \"超期较26Q1减少0.33M，TT无线项目交付范围主要包括4G站点新建、扩容以及改造，MBB场景为主，超期主要集中在站点在建0.55M，PAC滚动交付中，Q2评估结论：不计提专项。\"], [\"土耳其代表处\", \"土耳其\", \"运营商\", \"Turkey Vodafone DWDM\", \"0.28\", \"低\", \"1-2月\", \"波分项目交付，主要是0007922600100B合同站点在建超期0.22M，待设备全部发货后安装交付。\"], [\"东南欧代表处\", \"希腊\", \"数字能源\", \"Chirpan Solar Plant EOOD\", \"0.76\", \"低\", \"6-7月\", \"超期较26Q1减少4.64M，希腊数字能源Chirpan项目OY01002500150U合同站点递延存货0.66M，因控制权转移时点的判断发生变化（到达业主站点时发生转移，并非EPC站点），故25底反冲未到达业主站点前已触发的收入，因此产生超期递延存货5.40M。6月底13箱储能到货，对应收入已加回，剩余4个箱变预计7月初到货。\"], [\"东南欧代表处\", \"保加利亚\", \"数字能源\", \"PHOTOMATE s.r.o.\", \"0.56\", \"低\", \"5-6月\", \"主要是OY01002400110X合同受币种切换影响PSP口径128存货未聚合（GC口径128实际无超期余额），新账套虚发与GL反冲的PSP构造逻辑分别是：原始来源量价构造和调整来源COA加成构造，待整单合同收入触发后128可清零退出。\"], [\"德国代表处\", \"德国\", \"政企\", \"ARGE BSS Re-Invest\", \"0.35\", \"中\", \"6-10月\", \"德铁DB联合投标体项目交付已基本完成，待获取最终客户POD文档后触发收入，Q2专项减值评估结论为无需计提。\"], [\"土耳其代表处\", \"土耳其\", \"政企\", \"HIGH TECHNOLOGY Bilisim Sistemleri\", \"0.30\", \"待核实（原文：办）\", \"7-9月\", \"0Y07922500460V、OY07922500670Q合同超期在建存货0.24M，客户项目节奏缓慢，站点未ready，已到货光设备无法完成安装，待安装交付后触发收入。\"], [\"德国代表处\", \"德国\", \"运营商\", \"TDG NEMO Wireless Rollout Project\", \"0.24\", \"未提供\", \"4个月以上\", \"超期较26Q1减少0.18M，当前超期主要是在建存货0.19M，其中大部分站点已完成安装，待客户验收；少量站点安装计划取消，待回退或已回退中心仓，配置变更后清理站点存货。Q2评估结论：不计提专项。\"]]";
function renderInventoryBalanceCard(visible){let card=document.getElementById('inventory-balance-card');if(!card){card=document.createElement('section');card.id='inventory-balance-card';card.setAttribute('aria-labelledby','inventory-balance-title');const sub=['202605','202606','环比','波动'];card.innerHTML='<header><h2 id="inventory-balance-title">存货余额与减值</h2><span>202605 — 202606</span></header><div class="inventory-balance-scroll" tabindex="0" role="region" aria-label="存货余额与减值明细，可横向滚动"><table><thead><tr><th rowspan="2" scope="col">BG</th><th rowspan="2" scope="col">存货分类</th><th colspan="4" scope="colgroup">余额</th><th colspan="4" scope="colgroup">减值</th></tr><tr>'+[...sub,...sub].map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+inventoryBalanceRows.filter(r=>!['备件在途','备件在库'].includes(r[1])).map((r,i,rows)=>{const summary=!r[1];return '<tr class="'+(summary?(r[0]==='总计'?'inventory-total':'inventory-subtotal'):'')+'">'+(summary?'<th colspan="2" scope="row">'+r[0]+'</th>':(i===0||rows[i-1][0]!==r[0]?'<th rowspan="3" scope="rowgroup">'+r[0]+'</th>':'')+'<th scope="row">'+r[1]+'</th>')+r.slice(2).map(v=>'<td'+(String(v).trim().endsWith('%')&&Math.abs(parseFloat(v))>20?' class="inventory-over-threshold"':'')+'>'+(r[0]==='数字能源'&&r[1]==='区域仓存货'&&v==='-79.72%'?'<button type="button" class="inventory-region-drilldown" aria-label="分析数字能源区域仓存货波动 -79.72%">'+v+'</button>':v)+'</td>').join('')+'</tr>'}).join('')+'</tbody></table></div>';card.querySelector('.inventory-region-drilldown').onclick=()=>window.erpOneShowAnalysis?.('数字能源的区域仓存货波动为什么这么大？',inventoryRegionDetailResponse);document.getElementById('workspace-activity-tabs').after(card)}card.hidden=!visible}
